  quotes: ["我来迟了，不曾迎接远客！——王熙凤出场", "天下真有这样标致的人物，我今儿才算见了！——王熙凤赞黛玉", "这个妹妹我曾见过的。——贾宝玉初见黛玉"],
  analysis: ["黛玉视角的叙事功能：以黛玉初进贾府的陌生视角展开环境与人物描写，使读者如随黛玉步入贾府。步步留心时时在意的心理描写不仅刻画黛玉寄人篱下的孤介处境，更暗示其在贾府中始终如履薄冰的命运基调。", "王熙凤未见其人先闻其声：凤姐出场以笑声先于身影，在森严的贾母面前肆意放声，这种反差本身即暗示其在贾府的特殊地位。其后一连串夸赞黛玉、悲念丧妹、转悲为喜的表演，展现了凤姐八面玲珑的社交手腕与表演型人格。", "宝黛初见与摔玉的宿命：似曾相识的初见呼应第一回木石前盟的前世设定，为宝黛爱情赋予宿命色彩。宝玉因黛玉无玉而摔玉，表面是少年任性，深层是对自己与众不同之处的排斥——他不愿所爱之人有欠缺，这种以对方为标准的情感逻辑贯穿其一生。"]
