  quotes: ["贾不假，白玉为堂金作马。——护官符咏贾家", "丰年好大雪，珍珠如土金如铁。——护官符咏薛家", "阿房宫，三百里，住不下金陵一个史。——护官符咏史家"],
  analysis: ["护官符的社会批判：以四句俗谚概括贾史王薛四大家族的权势——白玉为堂、阿房宫住不下、龙王来请、珍珠如土。这些夸张的民间谣谚比任何正面的官场描写都更具批判力度，揭示权贵与官场盘根错节的利益同盟，是全书社会批判的核心意象。", "贾雨村的人格蜕变：从第一回受人恩惠的穷儒到第四回徇情枉法的贪官，雨村的蜕变展示了权力如何腐蚀人心。他明知英莲是恩人之女却仍胡乱判案，恩将仇报的行径揭示了官场对人性的异化。雨村是全书重要的反面参照，与宝玉形成价值观的根本对立。", "薄命女偏逢薄命郎的宿命：回目本身即点明命运的无常与不公。冯渊本欲娶英莲却遭横祸，英莲刚脱拐子之手又入薛蟠之掌，命运的每次转折都是从火坑跳入火坑。薄命二字贯穿英莲一生，也呼应全书千红一哭的主题。"]
