  questions: ["凤姐寿宴与宝玉祭奠的对比有何深意？","水仙庵洛神意象如何暗合金钏？","不了情反映了宝玉怎样的情感世界？"],
  overview: "本回以凤姐寿宴之热闹与宝玉祭奠金钏之冷清双线并写，繁华与死亡、欢愉与愧疚形成强烈对照，是宝玉情感世界与众不同的集中体现。",
