  analysis: ["攒金庆寿与撮土为香：繁华与死亡的并置。凤姐寿宴越热闹，宝玉祭奠越冷清，两相对照凸显宝玉与众不同的情感世界，他于众人的欢愉中独守对亡者的追念，'不了情'写其愧疚之深难了。", "水仙庵洛神之喻：以神写人。宝玉选水仙庵祭奠，因洛神意象暗合金钏投井而亡的结局，以神话之美寄托现实之悲，撮土为香是情感的仪式化升华，化俗事为深情。"]
