  analysis: ["凤姐泼醋：悍妒背后的婚姻悲剧。凤姐生日撞破奸情，其泼醋大闹表面是悍妒，深层是婚姻中不被忠诚对待的屈辱，贾琏持剑追赶更写尽夫妻反目的凶险，繁华寿宴瞬间变为婚姻战场。", "平儿理妆：妾室夹缝中的隐忍。平儿无端受屈，被宝玉接回理妆，宝玉之'喜出望外'写其以服务女儿为乐的心理，也反衬平儿在凤姐与贾琏之间两难求全的卑微处境，理妆之喜掩不住夹缝之苦。"]
