  questions: ["香菱学诗在全书中有何意义？","梦中得句象征什么？","香菱的雅化与其薄命命运有何张力？"],
  overview: "本回以薛蟠外出游艺与香菱入大观园学诗双线并写，是香菱命运中短暂的雅化时光，也是大观园诗意空间最温情的呈现之一。",
  background: "薛蟠被柳湘莲打后愧愤外出经商游艺，香菱随宝钗入住大观园。香菱素慕风雅，借此机会向黛玉求教作诗之法，苦吟不辍终在梦中得佳句。",
  quotes: ["博得嫦娥应借问，缘何不使永团圆——香菱（梦中得句）", "滥情人情误思游艺，慕雅女雅集苦吟诗——回目"],
  analysis: ["香菱学诗：苦学求雅的励志意象。香菱以憨痴之态苦吟不辍，梦中得句终成佳诗，这是全书最动人的励志场景，以苦学写对美的执着追求，也是薄命人对命运的诗意抵抗，越美越衬其日后之苦。", "黛玉教诗：以诗会友的雅趣。黛玉以王维杜甫为范教香菱作诗之法，展现其深厚的诗学修养，也写大观园诗教传统的温情。香菱的雅化与薛蟠的粗俗形成同一家族内的极端对照，雅俗判若云泥。"]
