  questions: ["怀古诗如何以古喻今？","胡庸医虎狼药有何寓意？","晴雯之病伏笔了什么？"],
  overview: "本回承上回宝琴怀古诗引发讨论，又写晴雯生病遇胡庸医乱用虎狼药，宝玉另请王太医诊治，雅与俗、诗与病并写。",
