  analysis: ["怀古诗之争：以删诗写审慎。宝钗建议删去怀古诗中涉及禁书的两首，体现其循规蹈矩的性格，而黛玉李纨反以为无妨，众人态度的差异折射性格分野，也为宝钗的世故再添一笔。", "胡庸医虎狼药：庸医害人的伏笔。胡庸医为晴雯开出虎狼之药被宝玉识破另请王太医，此事既写宝玉对女儿的细心呵护，也伏后文贾府败落时庸医误事，医与药的意象贯穿全书，病即命运的隐喻。"]
