  questions: ["宝琴旁观祭宗祠的视角有何意义？","除夕祭祠与元宵夜宴如何展现贾府全貌？","这一回的繁华描写如何伏衰败？"],
  overview: "本回写贾府除夕祭宗祠与元宵开夜宴两大礼仪场景，以宝琴旁观视角展现祭礼全貌，是贾府礼法气派与钟鸣鼎食之家的集中呈现。",
