  quotes: ["肝脑涂地，兆姓赖保育之恩；功名贯天，百代仰蒸尝之盛——贾府宗祠对联"],
  analysis: ["宝琴旁观祭宗祠：以客写主的视角。宝琴以外人身份旁观祭礼，使庄严礼仪如画卷徐徐展开，这种借客写主的写法既展现祭礼全貌又暗示贾府根脉的庄严，也以旁观者的新鲜感伏繁华将逝之叹。", "祭祠与夜宴：礼法气派的盛极之兆。除夕祭宗祠之庄严与元宵开夜宴之繁华并写，展现钟鸣鼎食之家的完整面貌。但繁华至此已极，盛极转衰的伏笔已暗藏其中，宗祠对联的赫赫之功反衬日后之零落。"]
