  questions: ["贾母破陈腐旧套反映了曹雪芹怎样的文学观？","凤姐效戏彩斑衣有何意味？","元宵夜宴的描写有何伏笔意义？"],
  overview: "本回借贾母批评才子佳人旧套表达曹雪芹的文学观，又写凤姐效老莱子戏彩斑衣逗贾母开心，是元宵夜宴的余波，也是全书文学理论的自觉呈现。",
  background: "元宵夜宴继续，贾母听女先儿说书，对才子佳人陈腐旧套大加批评。凤姐为讨贾母欢心，效老莱子彩衣娱亲之典逗趣，众人尽欢而散。",
  quotes: ["这些书都是一个套子，左不过是些佳人才子，最没趣儿——贾母", "鬼不成鬼，贼不成贼——贾母"],
  analysis: ["贾母破陈腐旧套：曹雪芹的文学宣言。贾母批评才子佳人小说的陈腐套路，实为曹雪芹借人物之口表达自己的文学观，强调写实与创新，是对当时小说窠臼的自觉反思，也是《红楼梦》自我定位的宣言。", "凤姐效戏彩斑衣：逢迎之术的极致。凤姐效老莱子彩衣娱亲之典，以自贬身份博贾母一笑，写其逢迎手段的高明。热闹中暗伏贾府以孝治家的伦理秩序与凤姐的生存智慧，戏彩背后是精明的算计。"]
