  quotes: ["我但凡是个男人，可以出得去，我必早走了，立一番事业——探春"],
  analysis: ["探春与赵姨娘之争：嫡庶矛盾的深层痛苦。赵姨娘为丧银辱骂亲生女儿探春，探春以理法战胜血缘之私。这不仅是银两之争，更是探春对庶出身份耻辱的痛苦抗争，'但凡是个男人'之叹道尽女儿身的不甘与无奈。", "刁奴欺幼主：大树将倾的征兆。吴新登家的等刁奴欺探春年幼故意刁难，被探春识破制服。刁奴蓄险心是贾府秩序松动的先兆，猢狲散之势已露端倪，越见探春之能越显贾府积弊之深。"]
