  questions: ["探春改革体现了怎样的治家才能？","宝钗小惠全大体有何智慧？","大观园经济化暗示了什么？"],
  overview: "本回写探春改革大观园管理兴利除弊，宝钗以小惠全大体照顾各方利益，是女儿治才的集中展现，也暗示大观园理想空间的经济化转型。",
