  quotes: ["一个破荷叶，一根枯草根子，都是值钱的——探春", "幸于始者怠于终，缮其辞者嗜其利——薛宝钗"],
  analysis: ["探春兴利除弊：女儿治才的集中展现。探春借鉴承包之法改革大观园管理，体现其政治眼光与魄力。但改革越见成效越暗示贾府积弊已深无力回天，是治才与命运的反讽，'破荷叶值钱'之悟终难挽大厦之倾。", "宝钗小惠全大体：识时务的处世智慧。宝钗令承包者拿部分收益分给众人，以恩惠巩固改革成果，'时'字写其识时务的圆融，与探春的刚形成互补。二人治道对照耐人寻味，大观园由此从诗意空间转向经济空间。"]
