  questions: ["紫鹃试玉反映了宝黛之间怎样的情感？","宝玉的疯迷说明了什么？","薛姨妈的安慰有何深意？"],
  overview: "本回写紫鹃以黛玉将回苏州之说试探宝玉真心，宝玉急痛攻心而疯迷；薛姨妈来安慰黛玉，暗藏金玉良缘的算计，慈与伪并存。",
