  quotes: ["慧紫鹃情辞试莽玉，慈姨妈爱语慰痴颦——回目", "若应了这门亲，倒是四角俱全——薛姨妈"],
  analysis: ["紫鹃试玉：以谎言试真情的慧心。紫鹃以黛玉将回苏州之说试探宝玉，宝玉急痛疯迷的剧烈反应印证了宝黛深情的不可动摇。紫鹃之慧在于以极端方式验证爱情，也为后文悲剧伏笔，试得越真越衬日后之痛。", "薛姨妈爱语慰痴颦：似慈实伪的算计。薛姨妈来安慰黛玉似慈母关怀，实则暗示金玉良缘的算计，将宝黛姻缘之说作为缓兵之计，'四角俱全'之言似成全实拖延，慈与伪的并存写尽世故人情的复杂。"]
