  overview: "本回写莺儿折柳编篮引发婆子与丫鬟冲突，芳官在绛芸轩受辱哭闹，宝玉召平儿调停，是大观园秩序崩坏的征兆。",
  background: "清明时节众人出游，莺儿等在柳叶渚折柳编花篮。大观园内婆子与丫鬟矛盾日深，春燕之姨娘何婆借故生事，芳官亦因洗头之事受干娘欺辱而哭闹。",
  quotes: ["柳叶渚边嗔莺咤燕，绛芸轩里召将飞符——回目"],
  analysis: ["柳叶渚折柳惹事：秩序崩坏的征兆。莺儿折柳编篮本是雅事，却引发婆子争执，雅趣变为闹剧，暗示大观园诗意空间已被世俗矛盾侵蚀，繁华表象下危机四伏，雅与俗的和谐已不可维持。", "召将飞符：将崩之垒的隐喻。宝玉召平儿以飞符调停芳官受辱之事，以军事术语写日常管理，暗示大观园已如将崩之垒需处处调兵遣将。秩序的瓦解已无可挽回，小事件折射大趋势。"]
