  imagery: "五美吟以古喻今，五位薄命美人的命运暗合黛玉及大观园女儿的悲剧。九龙佩是定情信物，与通灵宝玉金锁形成对照。幽淑女的诗与浪荡子的欲并写，雅与俗情与欲的张力跃然纸上。",
  questions: ["五美吟如何以古喻今？","九龙佩与通灵宝玉金锁有何对照？","幽淑女与浪荡子的并写有何深意？"],
  overview: "本回以黛玉作五美吟咏古代美人与贾琏以九龙佩私定尤二姐双线并写，雅与俗、诗与欲并置，是尤二姐悲剧的开端。",
  background: "贾敬丧事期间，贾琏在宁府帮忙，见尤二姐尤三姐而生垂涎之心。黛玉于此时作五美吟咏西施、虞姬、明妃、绿珠、红拂五位古代薄命美人，宝玉观之称赏。",
  quotes: ["肠断乌骓夜啸风，虞兮幽恨对重瞳——林黛玉《五美吟·虞姬》", "长揖雄谈态自殊，美人巨眼识穷途——林黛玉《五美吟·红拂》"],
  analysis: ["五美吟：以古喻今的命运映射。黛玉咏五位薄命美人，西施、虞姬、明妃、绿珠、红拂的命运暗合黛玉及大观园女儿的悲剧。以古人之命写今人之运，是诗谶的另一种形式，咏古即咏己。", "贾琏遗九龙佩：欲与雅的对照。贾琏以九龙佩为信物私定尤二姐，与通灵宝玉金锁的雅致定情形成对照。幽淑女的诗与浪荡子的欲并写，雅俗情欲的张力跃然纸上，也开启尤二姐悲剧的序幕。"]
