  questions: ["贾琏偷娶尤二姐反映了什么？","尤三姐思嫁柳湘莲有何意味？","二姐与三姐的性格对比有何意义？"],
  overview: "本回写贾琏在花枝巷偷娶尤二姐为外室，尤三姐立志改过倾心柳湘莲，是尤氏姐妹命运的关键转折，刚柔两种性格的对照初现。",
