  quotes: ["贾二舍偷娶尤二姨，尤三姐思嫁柳二郎——回目"],
  analysis: ["偷娶尤二姐：温柔乡即孽缘。贾琏偷娶尤二姐于花枝巷，以暗藏写欲望的放纵，温柔乡看似美好实为尤二姐厄运的开端。'偷'字写尽此事的不义与隐患，一时的快意埋下日后的杀机。", "尤三姐思嫁柳湘莲：浪子回头的渴望。尤三姐立志改过从良，倾心柳湘莲并表示非他不嫁，刚烈与柔情并存。但这种改过的渴望与柳湘莲的冷形成张力，伏下悲剧的远因，立志越坚反衬结局越惨。"]
