  analysis: ["黛玉思故里：飘零无根的孤寄命运。黛玉见苏州土仪触景思乡，土仪是乡愁的触发物，暗示其飘零无根的孤寄命运。思乡之悲与其在贾府的寄人篱下形成情感呼应，物之小触动了命之大悲。", "凤姐讯家童：阴狠机谋的布局。凤姐从兴儿口中盘问出贾琏偷娶尤二姐的全貌，暗中布局而非即时发作，写其阴狠深沉的机谋。这种隐忍不发比即时爆发更为可怕，尤二姐厄运已不可逆转。"]
