  quotes: ["胭脂鲜艳何相类，花之颜色人之泪——林黛玉《桃花行》", "好风频借力，送我上青云——薛宝钗《临江仙·柳絮》"],
  analysis: ["桃花行：以花喻人的命运写照。黛玉以桃花飘零喻己之命运，'花之颜色人之泪'将花与人泪等同，是诗谶的又一形式。重建诗社是黛玉对诗意的坚守也是繁华尾声的回光，越美越近终局。", "宝钗柳絮词夺魁：豪情暗伏得意。宝钗'好风频借力，送我上青云'一反悲愁传统，以豪情夺魁，暗伏其日后得意之兆。桃花与柳絮皆飘零之物却写出截然不同的人生态度，一悲一豪，命运分途已现。"]
