  analysis: ["姽婳词与芙蓉诔的对照：忠烈与含冤。姽婳词咏林四娘为王殉身的忠烈，芙蓉诔悼晴雯含冤而死的不公。一为报主一为含冤，以古人忠烈反衬今人冤屈，对照中见悲愤，烈与冤之间是世道的不公。", "芙蓉女儿诔：个人悲悼的升华。诔文以芙蓉喻晴雯高洁，将个人悼念升华为对女儿命运的普遍哀悼，是全书最长的祭文。'痴公子'之痴是情之极致，也是宝玉对大观园理想最后的祭奠，一诔祭尽群芳之悲。"]
