  quotes: ["宴海棠贾母赏花妖——回目上句","失宝玉通灵知奇祸——回目下句"],
  analysis: ["宴海棠花妖：回光返照的盛兆。海棠反季节开放是反常之兆，花妖象征繁华将尽的回光返照。贾母设宴赏花写其以喜掩忧，然花妖之妖已透不祥，反常之盛正是衰极之兆，呼应第九十四回作为全书转折的结构意义。","失通灵玉：灵性丧失的转折。通灵宝玉突然丢失是全书最重要的转折意象，玉失则宝玉失其灵性，预示大祸临头。通灵玉是宝玉与前世、与太虚幻境的唯一联结，玉失则顽石迷失本性，从灵性之人沦为痴傻之躯，是命运急转直下的关键。","花妖与失玉：盛衰骤转的结构。花妖的盛与失玉的衰并写，荣枯转换骤然。盛的极致即是衰的开端，花妖之宴恰成失玉之祸的背景，写盛衰一体、祸福相倚，是全书悲剧加速下行的结构枢纽。"]
