  questions: ["宝钗袭人双护玉有何深意？","恶子独承家反映了什么？","护玉与承家的对照有何意味？"],
  overview: "此回以宝钗袭人双护玉阻超凡与贾环等恶子聚党承家并写，佳人的守护与恶子的败坏对照，写败落后小人当道。",
